from ute_common_abstract_core.exceptions import AliasAlreadyAssignedError, AbstractUeLibException


class AliasAssignedToRunningObjectError(AliasAlreadyAssignedError):
    """Alias Assigned To Running Object Error"""

    def __str__(self):
        object_class_name = self.assigned_object.__class__.__name__
        err = f"alias '{self.alias}' already assigned to running {object_class_name} instance.\n"
        err += f"    You can not start two instances of {object_class_name} with same alias"
        return err


class ValueDiffersFromExpected(AbstractUeLibException):
    """Value on Ue differs than expected"""
    pass
